use std::collections::VecDeque;
use std::sync::Mutex;
use std::thread;
use std::time::{Duration, Instant};

/// Errors produced by the retry and rate-limiting machinery.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum RateLimitError {
    /// The operation failed after exhausting all retry attempts.
    MaxRetriesExceeded(String),
    /// The operation returned a non-retryable error.
    NonRetryable(String),
    /// The rate limiter rejected the request and no retries remain.
    RateLimited,
}

impl std::fmt::Display for RateLimitError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::MaxRetriesExceeded(msg) => write!(f, "max retries exceeded: {msg}"),
            Self::NonRetryable(msg) => write!(f, "non-retryable error: {msg}"),
            Self::RateLimited => write!(f, "rate limited"),
        }
    }
}

impl std::error::Error for RateLimitError {}

/// Configuration for retry behaviour.
#[derive(Debug, Clone)]
pub struct RetryConfig {
    /// Maximum number of attempts (including the first).
    pub max_attempts: u32,
    /// Initial backoff delay.
    pub initial_delay: Duration,
    /// Upper bound on the backoff delay.
    pub max_delay: Duration,
    /// Multiplier applied to the delay after each failed attempt.
    pub multiplier: f64,
}

impl Default for RetryConfig {
    fn default() -> Self {
        Self {
            max_attempts: 5,
            initial_delay: Duration::from_millis(100),
            max_delay: Duration::from_secs(5),
            multiplier: 2.0,
        }
    }
}

/// A sliding-window rate limiter.
///
/// Tracks the timestamps of recent permits inside a rolling time window.
/// When the number of permits inside the current window reaches `max_permits`,
/// new requests are rejected until old permits expire.
///
/// The implementation is `Send + Sync` and safe to share across threads.
pub struct SlidingWindowRateLimiter {
    max_permits: usize,
    window: Duration,
    timestamps: Mutex<VecDeque<Instant>>,
}

impl SlidingWindowRateLimiter {
    /// Create a new limiter that allows at most `max_permits` requests
    /// within any rolling `window` of time.
    pub fn new(max_permits: usize, window: Duration) -> Self {
        assert!(max_permits > 0, "max_permits must be > 0");
        assert!(!window.is_zero(), "window must be non-zero");
        Self {
            max_permits,
            window,
            timestamps: Mutex::new(VecDeque::with_capacity(max_permits)),
        }
    }

    /// Try to acquire a permit. Returns `true` if allowed, `false` if the
    /// current window is saturated.
    pub fn try_acquire(&self) -> bool {
        let now = Instant::now();
        let mut ts = self.timestamps.lock().expect("lock poisoned");

        // Evict timestamps that have fallen outside the window.
        while let Some(&front) = ts.front() {
            if now.duration_since(front) >= self.window {
                ts.pop_front();
            } else {
                break;
            }
        }

        if ts.len() < self.max_permits {
            ts.push_back(now);
            true
        } else {
            false
        }
    }

    /// Return how many permits are currently consumed inside the active window.
    pub fn current_count(&self) -> usize {
        let now = Instant::now();
        let mut ts = self.timestamps.lock().expect("lock poisoned");
        while let Some(&front) = ts.front() {
            if now.duration_since(front) >= self.window {
                ts.pop_front();
            } else {
                break;
            }
        }
        ts.len()
    }

    /// Return the time elapsed since the oldest permit still inside the window,
    /// or `None` if the window is empty.
    pub fn oldest_in_window(&self) -> Option<Duration> {
        let now = Instant::now();
        let ts = self.timestamps.lock().expect("lock poisoned");
        ts.front().map(|&t| now.duration_since(t))
    }
}

/// Retry an operation with exponential backoff, governed by a sliding-window
/// rate limiter.
///
/// # Arguments
/// * `limiter`   — shared rate limiter; each attempt consumes a permit.
/// * `config`    — retry / backoff parameters.
/// * `operation` — fallible closure that performs the work. Return `Ok(T)` to
///                 succeed, or `Err(String)` to signal a retryable failure.
///
/// # Behaviour
/// 1. Before each attempt the function calls `limiter.try_acquire()`. If the
///    limiter rejects, the attempt is deferred by the current backoff delay.
/// 2. If the operation itself fails, the delay is increased (capped at
///    `config.max_delay`) and the loop retries.
/// 3. After `config.max_attempts` the last error is returned as
///    `RateLimitError::MaxRetriesExceeded`.
pub fn retry_with_backoff<T, F>(
    limiter: &SlidingWindowRateLimiter,
    config: &RetryConfig,
    mut operation: F,
) -> Result<T, RateLimitError>
where
    F: FnMut() -> Result<T, String>,
{
    let mut delay = config.initial_delay;
    let mut last_err = String::new();

    for attempt in 0..config.max_attempts {
        // Respect the rate limiter.
        if !limiter.try_acquire() {
            if attempt + 1 >= config.max_attempts {
                return Err(RateLimitError::RateLimited);
            }
            thread::sleep(delay);
            delay = next_delay(delay, config);
            continue;
        }

        match operation() {
            Ok(val) => return Ok(val),
            Err(e) => {
                last_err = e;
                if attempt + 1 >= config.max_attempts {
                    return Err(RateLimitError::MaxRetriesExceeded(last_err));
                }
                thread::sleep(delay);
                delay = next_delay(delay, config);
            }
        }
    }

    Err(RateLimitError::MaxRetriesExceeded(last_err))
}

/// Compute the next delay, capping at `config.max_delay`.
fn next_delay(current: Duration, config: &RetryConfig) -> Duration {
    Duration::from_secs_f64(
        (current.as_secs_f64() * config.multiplier).min(config.max_delay.as_secs_f64()),
    )
}

