    // ---- SlidingWindowRateLimiter ------------------------------------------

    #[test]
    fn limiter_allows_up_to_max_permits() {
        let limiter = SlidingWindowRateLimiter::new(3, Duration::from_secs(1));
        assert!(limiter.try_acquire());
        assert!(limiter.try_acquire());
        assert!(limiter.try_acquire());
