        assert!(limiter.try_acquire()); // t=0
        thread::sleep(Duration::from_millis(60));
        assert!(limiter.try_acquire()); // t=60
        assert!(limiter.try_acquire()); // t=60
        assert!(!limiter.try_acquire()); // full

        // At t=60, the first permit (t=0) is still inside the 100ms window.
