        let mut handles = vec![];

        for _ in 0..4 {
            let l = Arc::clone(&limiter);
            handles.push(thread::spawn(move || l.try_acquire()));
        }

        let results: Vec<bool> = handles.into_iter().map(|h| h.join().unwrap()).collect();
        assert_eq!(results.iter().filter(|&&b| b).count(), 4);
