        let limiter = SlidingWindowRateLimiter::new(10, Duration::from_secs(1));
        let config = fast_config();
        let attempts_clone = Arc::clone(&attempts);

        let result = retry_with_backoff(&limiter, &config, || {
            let n = attempts_clone.fetch_add(1, Ordering::SeqCst);
            if n < 2 {
                Err(format!("transient failure #{n}"))
            } else {
                Ok("success")
            }
        });

        assert_eq!(result.unwrap(), "success");
        assert!(attempts.load(Ordering::SeqCst) >= 3);
    }

    #[test]
    fn retry_exhausts_attempts_on_persistent_failure() {
        let limiter = SlidingWindowRateLimiter::new(10, Duration::from_secs(1));
        let config = RetryConfig {
            max_attempts: 3,
            initial_delay: Duration::from_millis(1),
            max_delay: Duration::from_millis(5),
            multiplier: 2.0,
        };

        let result: Result<(), _> = retry_with_backoff(&limiter, &config, || {
            Err("always fails".to_string())
        });

        match result {
            Err(RateLimitError::MaxRetriesExceeded(msg)) => {
                assert!(msg.contains("always fails"));
