    #[test]
    fn retry_delays_increase_exponentially() {
        let attempts = Arc::new(AtomicU32::new(0));
        let limiter = SlidingWindowRateLimiter::new(100, Duration::from_secs(10));
        let config = RetryConfig {
            max_attempts: 4,
            initial_delay: Duration::from_millis(5),
            max_delay: Duration::from_millis(100),
            multiplier: 2.0,
        };
        let attempts_clone = Arc::clone(&attempts);
        let start = Instant::now();

        let _: Result<(), _> = retry_with_backoff(&limiter, &config, || {
            attempts_clone.fetch_add(1, Ordering::SeqCst);
            Err("fail".to_string())
        });

        let elapsed = start.elapsed();
        // 5 + 10 + 20 = 35ms minimum sleep across 3 retries
        assert!(elapsed >= Duration::from_millis(30));
        assert_eq!(attempts.load(Ordering::SeqCst), 4);
    }

    #[test]
    fn retry_respects_max_delay_cap() {
        let limiter = SlidingWindowRateLimiter::new(100, Duration::from_secs(10));
        let config = RetryConfig {
            max_attempts: 5,
            initial_delay: Duration::from_millis(50),
            max_delay: Duration::from_millis(60),
            multiplier: 10.0, // aggressive multiplier, but capped
        };
        let start = Instant::now();

        let _: Result<(), _> = retry_with_backoff(&limiter, &config, || {
            Err("fail".to_string())
        });

        let elapsed = start.elapsed();
        // With cap at 60ms, total sleep for 4 retries <= 4 * 60 = 240ms
        assert!(elapsed < Duration::from_millis(500));
    }

    #[test]
    fn retry_blocks_when_rate_limited() {
        // Only 1 permit per 50ms window.
        let limiter = SlidingWindowRateLimiter::new(1, Duration::from_millis(50));
        let config = RetryConfig {
            max_attempts: 3,
            initial_delay: Duration::from_millis(1),
            max_delay: Duration::from_millis(5),
            multiplier: 2.0,
        };

        // First acquire exhausts the window.
        assert!(limiter.try_acquire());

        // Now retry_with_backoff should hit rate limiting on each attempt,
        // sleeping through the window expiry before eventually succeeding.
        let start = Instant::now();
        let result = retry_with_backoff(&limiter, &config, || Ok(99));
        let elapsed = start.elapsed();

        assert_eq!(result.unwrap(), 99);
        // Should have slept at least once through the window.
        assert!(elapsed >= Duration::from_millis(40));
    }

